    "tcp": [
      {
        "type": "filter",
        "settings": {
          "allowedSourceIPs": ["geoip:cn", "10.0.0.0/8", "fd00::/8"],
          "blockedSourceIPs": ["10.20.0.0/16", "fd00:20::/48"]
        }
